const bin = items[0] && items[0].binary && items[0].binary.data;

if (!bin) {
  return [{ json: { error: 'Salida vacia del pipeline', stdout: '' } }];
}

let records;
let text = '';
try {
  // n8n 2.x guarda binarios en modo filesystem-v2: bin.data es un marcador,
  // NO base64. Forma soportada de leer el contenido (docs: Code node >
  // getBinaryDataBuffer).
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  text = buf.toString('utf-8');
  records = JSON.parse(text);
} catch (e) {
  return [{ json: { error: `JSON invalido en clasificado: ${e.message}`, stdout: String(text).slice(0, 300) } }];
}

if (!Array.isArray(records) || records.length === 0) {
  return [{ json: { error: 'El pipeline no devolvio registros (posible rate limit de Reddit)', count: 0 } }];
}

// Clasificacion y sentimiento NO se calculan aca: viven en osint_pipeline.py.
// Este nodo solo valida y mapea al esquema final. created_utc se pasa tal cual
// (YYYY-MM-DD HH:MM:SS UTC) para no desplazar la zona horaria.
return records
  .filter((r) => r && r.post_id && r.title)
  .map((r) => ({
    json: {
      post_id: String(r.post_id).slice(0, 300),
      title: String(r.title).slice(0, 500),
      content: r.content != null ? String(r.content).slice(0, 10000) : '',
      raw_content: r.raw_content != null ? String(r.raw_content).slice(0, 10000) : '',
      author: String(r.author || 'reddit'),
      subreddit: String(r.subreddit || ''),
      url: r.url != null ? String(r.url) : '',
      score: Number(r.score) || 0,
      num_comments: Number(r.num_comments) || 0,
      threat_category: String(r.threat_category || 'no_clasificado'),
      sentiment: String(r.sentiment || 'neutral'),
      compound: Number(r.compound) || 0,
      created_utc: r.created_utc ? String(r.created_utc) : null,
      source: String(r.source || 'reddit-rss')
    }
  }));

for (const item of items) {
  console.error(`[osint] Ciclo con errores: ${item.json.error || 'sin detalle'}`);
  if (item.json.stdout) {
    console.error(`[osint] stdout: ${String(item.json.stdout).slice(0, 800)}`);
  }
}
return items;

const total = items.length;
const porCategoria = items.reduce((acc, it) => {
  const c = it.json.threat_category || 'no_clasificado';
  acc[c] = (acc[c] || 0) + 1;
  return acc;
}, {});

console.log(`[osint] Ciclo OK: ${total} registros insertados/actualizados`, JSON.stringify(porCategoria));

return [{ json: { ciclos_ok: total, por_categoria: porCategoria } }];

// Nodo agregador: consolida los items en 1 solo item
// para que las estadisticas se ejecuten UNA sola vez por ciclo.
return [{ json: { trigger: true } }];
